INSERT INTO `settings` VALUES (1,'global','site_name','id','AKARRA','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(2,'global','tagline','id','Ecosystem of Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(3,'global','description','id','Ekosistem bisnis terintegrasi di bidang fashion, desain kreatif, event, dan periklanan digital.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(4,'global','founded_year','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(5,'global','address','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(6,'global','phone','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(7,'global','whatsapp','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(8,'global','email','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(9,'global','office_hours','id','Senin sampai Jumat, pukul 09.00 s.d. 17.00 WIB','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(10,'global','social','id','[{\"platform\":\"instagram\",\"url\":\"\",\"label\":\"Instagram\"},{\"platform\":\"tiktok\",\"url\":\"\",\"label\":\"TikTok\"},{\"platform\":\"linkedin\",\"url\":\"\",\"label\":\"LinkedIn\"}]','json','2026-08-21 13:26:46','2026-08-21 13:26:46'),(11,'global','nav','id','[{\"label\":\"Ekosistem\",\"path\":\"\\/ecosystem\"},{\"label\":\"Produk\",\"path\":\"\\/products\"},{\"label\":\"Layanan\",\"path\":\"\\/services\"},{\"label\":\"Artikel\",\"path\":\"\\/articles\"},{\"label\":\"Pendiri\",\"path\":\"\\/founders\"}]','json','2026-08-21 13:26:46','2026-08-22 05:11:19'),(12,'global','nav_cta_label','id','Mulai Percakapan','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(13,'global','footer_note','id','Seluruh hak cipta dilindungi.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(14,'global','og_image','id','null','string','2026-08-21 13:26:46','2026-08-22 05:11:24'),(15,'global','twitter_handle','id','','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(16,'home','hero_eyebrow','id','Warisan yang Sedang Dibangun','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(17,'home','hero_title','id','Ecosystem of Excellence','string','2026-08-21 13:26:46','2026-08-21 14:01:58'),(18,'home','hero_title_emphasis','id','Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(19,'home','hero_subtitle','id','Perpaduan yang canggih antara semangat Fashionpreneur, inovasi Creative Labs, dan keunggulan strategi periklanan. AKARRA dibangun untuk para visioner masa depan.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(20,'home','hero_cta_label','id','Jelajahi Ekosistem','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(21,'home','hero_secondary_cta_label','id','Filosofi Kami','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(22,'home','hero_image','id','null','string','2026-08-21 13:26:46','2026-08-22 03:36:20'),(23,'home','narrative_title','id','Membangun Warisan, Bukan Sekadar Bisnis','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(24,'home','narrative_body','id','AKARRA bergerak di industri fashion, desain kreatif, event, dan periklanan digital. Melalui tiga pilar utama, kami tidak hanya menjual produk, tetapi membangun identitas dan dampak nyata bagi komunitas fashion dan kreatif Indonesia.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(25,'home','narrative_image','id','http://localhost:8000/storage/settings/2026/08/SfSZs6tS73hCToZkz6pPVDPu.png','string','2026-08-21 13:26:46','2026-08-22 03:39:15'),(26,'home','narrative_quote','id','Kami percaya bahwa prestise sejati lahir dari titik temu antara presisi yang terukur dan jiwa seni. Perjalanan kami adalah tentang menciptakan dampak yang bergema lintas generasi.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(27,'home','narrative_quote_attribution','id','Para Pendiri AKARRA','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(28,'home','narrative_badge','id','Est. 2024','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(29,'home','values','id','[{\"name\":\"Excellence\",\"body\":\"Kualitas tanpa kompromi di setiap jahitan, bingkai, dan strategi yang kami kerjakan.\"},{\"name\":\"Integrity\",\"body\":\"Membangun kepercayaan melalui transparansi dan kepemimpinan yang beretika di setiap lini.\"},{\"name\":\"Innovation\",\"body\":\"Menembus batas melalui eksperimen kreatif dan teknologi modern.\"},{\"name\":\"Elegance\",\"body\":\"Komitmen pada estetika yang halus, berbicara tanpa perlu berteriak.\"}]','json','2026-08-21 13:26:46','2026-08-21 14:20:37'),(30,'home','services_eyebrow','id','Tiga Pilar Kami','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(31,'home','services_title','id','Ekosistem Layanan','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(32,'home','services_subtitle','id','Tiga pilar yang saling menopang, dirancang untuk menemani brand di setiap tahap pertumbuhannya.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(33,'home','services_cta_label','id','Lihat seluruh layanan','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(34,'home','solutions_title','id','Solusi Pilihan','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(35,'home','solutions_subtitle','id','Rangkaian produk dan karya yang lahir dari ekosistem kami.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(36,'home','solutions','id','[{\"title\":\"Bespoke Collection\",\"body\":\"Keunggulan yang dijahit khusus untuk eksekutif masa kini.\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/yeHZ8rf20mBBMcjVcUYJQnoT.png\",\"category\":\"Fesyen\"},{\"title\":\"Signature Textiles\",\"body\":\"Kurasi kain kelas dunia dengan sumber yang beretika.\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/lLRJ4k0eWg9xGuXF1TQXLdB7.png\",\"category\":\"Fesyen\"},{\"title\":\"Visual Storytelling\",\"body\":\"Narasi visual yang membangun kedekatan emosional dengan audiens.\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/iIocgYCA8koGjMc61MRDmhJq.jpg\",\"category\":\"Kreatif\"},{\"title\":\"Brand Positioning\",\"body\":\"Strategi penempatan brand yang tajam dan terukur di pasar digital.\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/DpSmLgRL2OnKU2gEV2nx0B6G.jpg\",\"category\":\"Periklanan\"}]','json','2026-08-21 13:26:46','2026-08-22 05:14:03'),(37,'home','story_title','id','Cerita di Balik AKARRA','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(38,'home','story_body','id','Kami percaya setiap brand memiliki cerita yang layak diceritakan dengan elegan. Bersama kami, Anda tidak hanya membangun bisnis, tetapi juga membangun warisan.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(39,'home','story_image','id','/images/content/home-story.jpg','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(40,'home','story_video','id','http://localhost:8000/storage/settings/2026/08/O09gkXdYgLQYheejYBLGGK1j.mp4','string','2026-08-21 13:26:46','2026-08-22 03:36:20'),(41,'home','founders_title','id','Kenali Para Pendiri','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(42,'home','founders_subtitle','id','Dua orang di balik arah dan standar AKARRA.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(43,'home','form_title','id','Mari Berkolaborasi','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(44,'home','form_subtitle','id','Konsultasi awal gratis, tanpa komitmen. Ceritakan apa yang sedang Anda bangun.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(45,'home','form_cta_label','id','Kirim pesan','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(46,'ecosystem','hero_eyebrow','id','Arsitektur dari Sebuah Aspirasi','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(47,'ecosystem','hero_title','id','Ecosystem of Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(48,'ecosystem','hero_title_emphasis','id','Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(49,'ecosystem','hero_subtitle','id','Sebuah ruang lintas disiplin tempat presisi bertemu puisi. AKARRA bukan sekadar sebuah brand; ia adalah lanskap indrawi yang menyatu, tempat fashion, seni, dan strategi melebur menjadi satu standar yang prestisius.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(50,'ecosystem','story_title','id','Cerita Kami','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(51,'ecosystem','story_body','id','AKARRA didirikan oleh Febri Khoirul Imam dan Nanda Fifia Putri, lahir dari visi untuk menciptakan platform bisnis yang tidak hanya menjual produk, tetapi juga membangun identitas dan dampak nyata bagi komunitas fashion dan kreatif Indonesia.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(52,'ecosystem','philosophy_title','id','Filosofi Nama & Logo','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(53,'ecosystem','philosophy_body','id','Logo AKARRA terinspirasi dari geometri berlian dan mandala tradisional, perpaduan antara kemewahan modern dan kearifan lokal.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(54,'ecosystem','philosophy_items','id','[{\"title\":\"Berlian & Kemewahan\",\"body\":\"Struktur geometris berlian mencerminkan kualitas premium dan eksklusivitas.\"},{\"title\":\"Energi & Dinamisme\",\"body\":\"Segitiga yang saling bertautan melambangkan inovasi dan kolaborasi.\"},{\"title\":\"Mandala & Harmoni\",\"body\":\"Pola melingkar mengacu pada tradisi mandala Nusantara.\"},{\"title\":\"Emas & Kepercayaan\",\"body\":\"Warna emas melambangkan prestise dan kepercayaan.\"}]','json','2026-08-21 13:26:46','2026-08-21 13:26:46'),(55,'ecosystem','standard_title','id','The AKARRA Standard','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(56,'ecosystem','standard_body','id','Standar tertinggi di setiap produk dan layanan, sesuai nilai Excellence dan Elegance yang kami pegang.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(57,'ecosystem','standard_image','id','http://localhost:8000/storage/settings/2026/08/Riuja9nv1G8wCTrrNtB0rEZz.jpg','string','2026-08-21 13:26:46','2026-08-22 05:14:36'),(58,'ecosystem','values','id','[{\"name\":\"Excellence\",\"label\":\"Keunggulan\",\"body\":\"Standar tertinggi dalam setiap produk dan layanan.\"},{\"name\":\"Integrity\",\"label\":\"Integritas\",\"body\":\"Transparansi dan kepercayaan di setiap kemitraan.\"},{\"name\":\"Innovation\",\"label\":\"Inovasi\",\"body\":\"Terus berevolusi dan berpikir di luar konvensi.\"},{\"name\":\"Collaboration\",\"label\":\"Kolaborasi\",\"body\":\"Tumbuh bersama klien, mitra, dan komunitas kreatif.\"},{\"name\":\"Elegance\",\"label\":\"Elegansi\",\"body\":\"Estetika dan keindahan dalam setiap karya.\"}]','json','2026-08-21 13:26:46','2026-08-21 13:26:46'),(59,'ecosystem','vision_title','id','Visi Global untuk Kesuksesan Bersama','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(60,'ecosystem','vision_body','id','Menjadi ekosistem bisnis fashion dan kreatif terdepan di Indonesia yang melahirkan brand-brand berkelas dunia dengan akar budaya lokal.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(61,'ecosystem','mission','id','[\"Membangun platform fashion terintegrasi dari produksi hingga distribusi.\",\"Menghadirkan layanan desain dan event kreatif berkelas premium.\",\"Memperkuat brand lokal melalui strategi digital dan periklanan inovatif.\",\"Menciptakan ekosistem kolaboratif untuk pelaku industri kreatif Indonesia.\",\"Mendorong pertumbuhan bisnis klien melalui solusi holistik dan terukur.\"]','json','2026-08-21 13:26:46','2026-08-21 13:26:46'),(62,'ecosystem','stats','id','[{\"value\":\"12\",\"label\":\"Atelier Global\"},{\"value\":\"450+\",\"label\":\"Pengrajin\"},{\"value\":\"24\",\"label\":\"Mitra Strategis\"},{\"value\":\"100%\",\"label\":\"Sumber Berkelanjutan yang Etis\"}]','json','2026-08-21 13:26:46','2026-08-21 14:20:37'),(63,'products','hero_eyebrow','id','Koleksi Pilihan','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(64,'products','hero_title','id','The Artifacts of Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(65,'products','hero_title_emphasis','id','Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(66,'products','hero_subtitle','id','Jelajahi ekosistem produk AKARRA, tempat logika berkinerja tinggi bertemu dengan keahlian tangan pengrajin. Solusi kami dirancang bagi mereka yang menuntut hasil tanpa kompromi.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(67,'products','textile_title','id','Rekayasa Tekstil & Fashion','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(68,'products','textile_body','id','Busana yang dijahit dengan presisi, mendefinisikan ulang identitas kalangan atas melalui serat langka dan siluet arsitektural.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(69,'products','items','id','[{\"name\":\"The Meridian Suite\",\"label\":\"Edisi Terbatas 01\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/bxE2tNoKTtVC6ItTBzxn4YL4.jpg\",\"tag\":\"Reservasi\"},{\"name\":\"Artisanal Accents\",\"label\":\"Inovasi Serat\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/AQlxvtpd2H3HYj59vEfYsM7H.jpg\",\"tag\":\"Jelajahi\"}]','json','2026-08-21 13:26:46','2026-08-22 05:15:39'),(70,'products','labs_title','id','AKARRA Labs','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(71,'products','labs_body','id','Ruang eksperimen desain dan pengembangan produk, tempat ide diuji sebelum menjadi karya.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(72,'products','labs','id','[{\"title\":\"Material Bio-Synthesis\",\"body\":\"Mengembangkan alternatif berkelanjutan hasil rekayasa laboratorium untuk material langka pada interior mewah.\"},{\"title\":\"Cognitive Branding\",\"body\":\"Sebuah metodologi untuk membangun resonansi brand melalui prinsip neuro-estetika dan pemetaan sensorik.\"}]','json','2026-08-21 13:26:46','2026-08-21 14:20:37'),(73,'products','whitepaper','id','{\"label\":\"Studi Eksperimental 042\",\"title\":\"Kecerdasan Spasial\",\"body\":\"Merevolusi interaksi antarmuka manusia melalui umpan balik biologis dan pemodelan spasial prediktif.\",\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/dxj38e4VTYWGKRZ0aKd43PXW.jpg\"}','json','2026-08-21 13:26:46','2026-08-22 05:15:39'),(74,'products','digital_title','id','Dominasi Strategis di Ranah Digital','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(75,'products','digital_body','id','Perencanaan dan eksekusi kampanye digital yang terukur, dari penempatan media hingga pengelolaan performa.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(76,'products','digital_items','id','[{\"title\":\"Penguasaan Omnichannel\",\"body\":\"Mengintegrasikan narasi brand secara mulus di lebih dari 12 titik sentuh untuk pengalaman pengguna yang menyatu dan eksklusif.\"},{\"title\":\"Narasi Berbasis Data\",\"body\":\"Memanfaatkan algoritma eksklusif untuk memprediksi pergeseran budaya dan memposisikan brand selangkah lebih maju.\"},{\"title\":\"Visual Berkonversi Tinggi\",\"body\":\"Standar produksi sinematik yang diterapkan pada iklan programatik demi prestise dan ROI maksimal.\"}]','json','2026-08-21 13:26:46','2026-08-21 14:20:37'),(77,'products','cta_title','id','Siap mendefinisikan ulang standar Anda?','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(78,'products','cta_subtitle','id','Model kerja sama klien terbatas kami memastikan setiap kemitraan mendapatkan perhatian penuh dari seluruh kekuatan strategi dan kreativitas AKARRA.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(79,'products','cta_label','id','Ajukan Audit','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(80,'products','cta_secondary_label','id','Gabung Daftar Tunggu','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(81,'services','hero_title','id','Architecting Excellence.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(82,'services','hero_title_emphasis','id','Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(83,'services','hero_subtitle','id','Apa yang kami kerjakan bersama Anda, dari ide pertama hingga brand yang dikenal.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(84,'services','hero_image','id','http://localhost:8000/storage/settings/2026/08/3WguMOu63aDaYTYLxhcGFkPx.jpg','string','2026-08-21 13:26:46','2026-08-22 05:18:27'),(85,'services','hero_eyebrow','id','Kapabilitas Kami','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(86,'services','pillars','id','[{\"name\":\"Fashionpreneur\",\"label\":\"Infrastruktur\",\"body\":\"Ekosistem menyeluruh bagi desainer mapan maupun label baru untuk tumbuh dengan tetap menjaga integritas. Kami menangani kerumitan rantai pasok agar Anda bisa fokus pada jiwa brand Anda.\",\"items\":[\"Industri Pakaian Jadi\",\"Perdagangan Besar Pakaian\",\"Distribusi & Retail\"],\"bullets\":[\"Pengembangan Brand\",\"Sumber Tekstil\",\"Produksi Atelier\",\"Strategi Distribusi\"],\"subcards\":[{\"title\":\"The Atelier\",\"body\":\"Pembuatan sampel khusus dan penggambaran pola teknis untuk siluet mode tingkat tinggi.\",\"bullets\":[\"Sampling Haute Couture\",\"Pengembangan Tech Pack\"]},{\"title\":\"Global Production\",\"body\":\"Produksi skala kecil yang beretika dan pengadaan tekstil skala besar dengan fokus pada keberlanjutan.\",\"bullets\":[\"Sumber yang Etis\",\"Manajemen Kendali Mutu\"]}],\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/kfzsveKx21tROaS71YF8LIcS.jpg\"},{\"name\":\"Creative Labs\",\"label\":\"Identitas\",\"body\":\"Mesin intelektual AKARRA. Kami menerjemahkan jiwa brand menjadi narasi visual dan pengalaman yang bergema di hadapan audiens global yang jeli.\",\"items\":[\"Desain Grafis & Branding\",\"Produksi Konten\",\"Event & Pertunjukan\"],\"bullets\":[\"Narasi Visual\",\"Inovasi UI\\/UX\",\"Fotografi & Sinema\",\"Desain Eksperimental\"],\"subcards\":[{\"title\":\"Art Direction\",\"body\":\"Kurasi identitas visual, citra kampanye, dan pedoman brand dengan standar tinggi.\",\"bullets\":[\"Strategi Visual\",\"Desain Identitas\"]},{\"title\":\"Immersive Events\",\"body\":\"Peluncuran produk dan gelaran runway yang dirancang khusus untuk membangkitkan kecerdasan emosional.\",\"bullets\":[\"Desain Ruang\",\"Kurasi Tamu\"]}],\"image\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/HcA1NG2lhTyuIJuMyYpAEQzA.jpg\"},{\"name\":\"Advertising\",\"label\":\"Periklanan & Strategi Digital\",\"body\":\"Strategi digital dan periklanan inovatif untuk memperkuat posisi brand di pasar.\",\"items\":[\"Strategi Digital\",\"Media Placement\",\"Social Media Management\"],\"bullets\":[\"Positioning Brand\",\"Penetrasi Pasar\",\"Pertumbuhan Digital\",\"Media Strategis\"],\"image\":null}]','json','2026-08-21 13:26:46','2026-08-22 05:18:27'),(87,'services','gallery','id','[\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/15S2qzNfOwfnNX2FqrqQmop3.jpg\",\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/tGVY3wT9vkQ6gOA7kJnFzBIS.jpg\",\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/hWNqawPpqeMESVJsTj7VSBAq.jpg\",\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/WwTwqEVaNKZqCmIi2OOzix4V.jpg\",\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/788q1kioDA3Q5cM5o2IJW4jW.jpg\"]','json','2026-08-21 13:26:46','2026-08-22 05:17:21'),(88,'services','growth_title','id','Strategi & Pertumbuhan Digital','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(89,'services','growth_body','id','Presisi berbasis data bertemu intuisi kreatif. Kami tidak sekadar menemukan audiens Anda; kami menumbuhkan komunitas pendukung setia.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(90,'services','amplification_cards','id','[{\"title\":\"Strategi Digital\",\"body\":\"Analisis pasar menyeluruh dan pemetaan pertumbuhan untuk sektor premium.\",\"bullets\":[\"Intelijen Pasar\",\"Optimalisasi Funnel\"]},{\"title\":\"Produksi Konten\",\"body\":\"Video kelas atas, fotografi editorial, dan penceritaan interaktif.\",\"bullets\":[\"Video Editorial 4K\",\"Narasi Sosial\"]},{\"title\":\"Pertumbuhan Brand\",\"body\":\"Kemitraan strategis, seeding influencer, dan ekspansi global.\",\"bullets\":[\"PR Strategis\",\"Ekspansi Lintas Negara\"]}]','json','2026-08-21 13:26:46','2026-08-21 14:20:37'),(91,'services','why_title','id','Mengapa AKARRA','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(92,'services','why_items','id','[{\"title\":\"Ekosistem lengkap dalam satu atap\",\"body\":\"Produksi fashion, desain kreatif, event, hingga periklanan digital ditangani satu mitra.\"},{\"title\":\"Kualitas premium & elegan\",\"body\":\"Standar tertinggi di setiap produk dan layanan.\"},{\"title\":\"Berakar pada budaya lokal\",\"body\":\"Brand berkelas dunia tanpa melepaskan akar budaya Indonesia.\"},{\"title\":\"Kolaboratif & transparan\",\"body\":\"Kami tumbuh bersama klien, mitra, dan komunitas kreatif.\"},{\"title\":\"Solusi holistik & terukur\",\"body\":\"Pendampingan dari ide pertama hingga eksekusi.\"}]','json','2026-08-21 13:26:46','2026-08-21 13:26:46'),(93,'services','cta_title','id','Siap mendefinisikan ulang warisan Anda?','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(94,'services','cta_subtitle','id','Konsultasi awal gratis, tanpa komitmen.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(95,'services','cta_label','id','Mulai kolaborasi','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(96,'services','cta_secondary_label','id','Concierge@akarra.com','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(97,'founders','hero_eyebrow','id','Arsitek Nilai','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(98,'founders','hero_title','id','The Stewardship of Legacy.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(99,'founders','hero_title_emphasis','id','Legacy','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(100,'founders','hero_subtitle','id','AKARRA didirikan atas prinsip bahwa keunggulan bukanlah sebuah tindakan, melainkan kebiasaan. Kepemimpinan kami berdedikasi penuh pada pembinaan kekayaan, kebijaksanaan, dan warisan abadi yang cermat bagi para visioner masa kini.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(101,'founders','people','id','[{\"name\":\"Febri Khoirul Imam\",\"role\":\"Direktur Utama\",\"body\":\"Dengan pengalaman lebih dari dua dekade dalam investasi strategis dan manajemen institusional, Febri Khoirul Imam memimpin AKARRA dengan fokus pada ketahanan struktural dan pelestarian modal jangka panjang. Latar belakangnya di pasar keuangan global menjadi tulang punggung analitis bagi ekosistem-ekosistem paling ambisius AKARRA.\",\"portrait\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/6nSGvnK2vgmnocHjUhkzQpZN.jpg\",\"quote\":\"Warisan bukanlah apa yang kita tinggalkan untuk orang lain, melainkan apa yang kita tanamkan dalam diri mereka. Di AKARRA, kami membangun kerangka kerja tempat dampak itu bisa bertahan lama.\",\"legacy_body\":\"Febri percaya bahwa membangun sebuah warisan membutuhkan lebih dari sekadar kesuksesan finansial; dibutuhkan komitmen pada keunggulan di setiap detail. Filosofinya berpusat pada \'Integrated Stewardship\' — keyakinan bahwa kekayaan dan pengaruh harus dikelola sebagai satu kesatuan yang utuh dan penuh tujuan.\"},{\"name\":\"Nanda Fifia Putri\",\"role\":\"Komisaris\",\"body\":\"Nanda Fifia Putri membawa perspektif yang halus ke dalam jajaran AKARRA, dengan keahlian dalam warisan brand dan tata kelola filantropi. Kariernya dibentuk oleh titik temu antara dunia budaya tinggi dan keuangan tingkat atas, memastikan produk dan layanan AKARRA tetap menjaga jiwanya seiring pertumbuhan skala bisnis.\",\"portrait\":\"http:\\/\\/localhost:8000\\/storage\\/settings\\/2026\\/08\\/b4PClzlPHjsjNyvl7a6gptYZ.jpg\",\"quote\":\"Kepemimpinan visioner adalah tentang melihat benang-benang tak kasat mata yang menghubungkan keputusan hari ini dengan warisan hari esok.\",\"legacy_body\":\"Filosofi Nanda berakar pada \'Cultural Capital.\' Ia menjunjung pelestarian nilai (values) yang berjalan seiring dengan nilai ekonomi (value), memastikan brand AKARRA menjadi penanda prestise dan kedalaman intelektual bagi generasi mendatang.\"}]','json','2026-08-21 13:26:46','2026-08-22 05:18:45'),(102,'founders','quote','id','Fondasi yang dibangun di atas integritas, masa depan yang dibentuk oleh visi.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(103,'founders','cta_title','id','Bergabunglah dengan Lingkaran Utama.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(104,'founders','cta_subtitle','id','Rasakan layanan penasihat khusus dan ekosistem yang mendefinisikan gaya hidup AKARRA.','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(105,'founders','cta_label','id','Ajukan Konsultasi','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(106,'founders','cta_secondary_label','id','Lihat Ekosistem','string','2026-08-21 13:26:46','2026-08-21 14:20:37'),(107,'global','site_name','en','AKARRA','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(108,'global','tagline','en','Ecosystem of Excellence','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(109,'global','description','en','Ekosistem bisnis terintegrasi di bidang fashion, desain kreatif, event, dan periklanan digital.','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(110,'global','founded_year','en','null','string','2026-08-21 13:26:46','2026-08-22 05:11:19'),(111,'global','address','en','null','string','2026-08-21 13:26:46','2026-08-22 05:11:19'),(112,'global','phone','en','null','string','2026-08-21 13:26:46','2026-08-22 05:11:19'),(113,'global','whatsapp','en','6285179973943','string','2026-08-21 13:26:46','2026-08-22 05:11:19'),(114,'global','email','en','null','string','2026-08-21 13:26:46','2026-08-22 05:11:19'),(115,'global','office_hours','en','Senin sampai Jumat, pukul 09.00 s.d. 17.00 WIB','string','2026-08-21 13:26:46','2026-08-21 13:26:46'),(116,'global','social','en','[{\"platform\":\"instagram\",\"url\":null,\"label\":\"Instagram\"},{\"platform\":\"tiktok\",\"url\":null,\"label\":\